/* Finite wheel inertia. Native touch, keyboard and nested panel scrolling stay native. */
(()=>{'use strict';
const root=document.documentElement,reduced=matchMedia('(prefers-reduced-motion: reduce)');let frame=0,last=0,target=scrollY;
const allowed=()=>!document.hidden&&!reduced.matches&&!root.classList.contains('motion-off')&&!root.classList.contains('panel-open')&&!root.classList.contains('image-focused')&&!navigator.connection?.saveData;
function stop(){cancelAnimationFrame(frame);frame=0;last=0;target=scrollY;}
function nested(node){for(let el=node;el&&el!==document.body&&el!==root;el=el.parentElement){if(el.matches?.('input,textarea,select,[contenteditable="true"],dialog')||(/auto|scroll/.test(getComputedStyle(el).overflowY)&&el.scrollHeight>el.clientHeight+1))return true;}return false;}
function tick(time){frame=0;if(!allowed()){stop();return;}const dt=last?Math.min(.05,(time-last)/1000):1/60;last=time;target=Math.min(Math.max(0,root.scrollHeight-innerHeight),Math.max(0,target));const next=scrollY+(target-scrollY)*(1-Math.exp(-8*dt));if(Math.abs(target-next)<.35){scrollTo({top:target,behavior:'instant'});last=0;return;}scrollTo({top:next,behavior:'instant'});frame=requestAnimationFrame(tick);}
addEventListener('wheel',event=>{if(!allowed()||event.defaultPrevented||event.ctrlKey||event.metaKey||event.altKey||Math.abs(event.deltaX)>Math.abs(event.deltaY)||nested(event.target)){stop();return;}const delta=event.deltaY*(event.deltaMode===1?18:event.deltaMode===2?innerHeight:1);if(!delta)return;const limit=Math.max(0,root.scrollHeight-innerHeight);if(!frame)target=scrollY;target=Math.min(limit,Math.max(0,target+delta));if(Math.abs(target-scrollY)<.01)return;event.preventDefault();if(!frame){last=0;frame=requestAnimationFrame(tick);}},{passive:false});
addEventListener('pointerdown',stop,{passive:true});addEventListener('touchstart',stop,{passive:true});addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','PageUp','PageDown','Home','End',' ','Escape'].includes(e.key))stop();});addEventListener('resize',stop,{passive:true});addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});reduced.addEventListener('change',stop);new MutationObserver(()=>{if(!allowed())stop();}).observe(root,{attributes:true,attributeFilter:['class']});
})();
